CREATE TABLE IF NOT EXISTS cms_import_jobs(id BIGSERIAL PRIMARY KEY,source_type VARCHAR(40) NOT NULL,source_fingerprint VARCHAR(128) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','completed','failed')),cursor_value TEXT,stats_json TEXT NOT NULL DEFAULT '{}',options_json TEXT NOT NULL DEFAULT '{}',last_error TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_import_mappings(job_id BIGINT NOT NULL REFERENCES cms_import_jobs(id) ON DELETE CASCADE,source_kind VARCHAR(80) NOT NULL,source_id VARCHAR(190) NOT NULL,target_kind VARCHAR(80) NOT NULL,target_id BIGINT NOT NULL,metadata_json TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(job_id,source_kind,source_id));
CREATE TABLE IF NOT EXISTS cms_import_media(job_id BIGINT NOT NULL REFERENCES cms_import_jobs(id) ON DELETE CASCADE,source_url TEXT NOT NULL,target_media_id BIGINT,sha256 VARCHAR(64),status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','imported','skipped','failed')),last_error TEXT,PRIMARY KEY(job_id,source_url));
CREATE TABLE IF NOT EXISTS cms_import_reports(id BIGSERIAL PRIMARY KEY,job_id BIGINT NOT NULL REFERENCES cms_import_jobs(id) ON DELETE CASCADE,report_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
